/**
 * Yields every organization id in id order, reading one keyset page at a time
 * until the table runs out. A sweep that walks this covers every workspace
 * however many there are; a single fixed-size query would only ever see the
 * first page. Deleted workspaces are skipped unless the scope includes them.
 */
export async function* iterateOrgIds(
  pageSize: number,
  scope: ArchiveScope = {},
): AsyncGenerator<OrgId> {
  const size = Math.max(1, pageSize);
  let afterId: string | null = null;

  for (;;) {
    const rows = getDb()
      .select({ id: organizations.id })
      .from(organizations)
      .where(
        and(
          livePredicate(organizations.archivedAt, scope),
          afterId === null ? undefined : gt(organizations.id, afterId),
        ),
      )
      .orderBy(asc(organizations.id))
      .limit(size)
      .all();

    for (const row of rows) yield brandId<OrgId>(row.id);

    const last = rows.at(-1);
    if (!last || rows.length < size) return;
    afterId = last.id;
  }
}

