import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
const PAST = "2026-01-01T00:00:00.000Z";
const NOW = new Date("2026-06-01T07:00:00.000Z");
const NEVER = new Date(0).toISOString();

async function insertLateIssue(tenant: Tenant) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  return issueRepo.insertIssue(
    issueInput(tenant.org.id, tenant.project.id, { title: "late", dueAt: PAST }),
    tenant.userIds.owner,
    number,
  );
}

async function allLiveIds(pageSize = 7): Promise<string[]> {
  const ids: string[] = [];
  for await (const id of orgRepo.iterateOrgIds(pageSize)) ids.push(id);
  return ids;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  resetOverdueTracking();
});

afterAll(() => {
  cleanup();
});

describe("scratch: full-coverage sweeps", () => {
  it("iterateOrgIds yields every live org in id order across pages", async () => {
    const tenants: Tenant[] = [];
    for (let i = 0; i < 60; i += 1) tenants.push(await createTenant(`scratch-iter-${i}`));
    const gone = await createTenant("scratch-iter-gone");
    await orgRepo.archiveOrg(gone.org.id);

    const live = await allLiveIds(7);
    expect(live).toHaveLength(61);
    expect(live).toEqual([...live].sort());
    expect(live).not.toContain(gone.org.id);
    for (const t of tenants) expect(live).toContain(t.org.id);

    const everything: string[] = [];
    for await (const id of orgRepo.iterateOrgIds(7, { includeArchived: true })) everything.push(id);
    expect(everything).toContain(gone.org.id);
    expect(everything).toHaveLength(62);
  });

  it("overdue scan announces an overdue issue in every live org, past the old 50-org limit", async () => {
    const seen = new Set<string>();
    const detach: Unsubscribe = subscribe("issue.overdue", (payload) => {
      seen.add(payload.orgId);
    });

    const ids = await allLiveIds();
    const tenantsWithIssue: Tenant[] = [];
    // Only the first 60 orgs created in the previous test get an overdue issue here.
    for (const id of ids.slice(0, 60)) {
      const row = await orgRepo.findOrgById(id as never);
      if (!row) continue;
      const t = { org: row, project: null as never, actors: null as never, userIds: null as never } as Tenant;
      tenantsWithIssue.push(t);
    }
    // Re-use fixture projects: look up each org's first project.
    const { getDb, projects } = await import("@/server/db");
    const { eq } = await import("drizzle-orm");
    for (const t of tenantsWithIssue) {
      const project = getDb().select().from(projects).where(eq(projects.orgId, t.org.id)).get();
      const owner = t.org.ownerId;
      const number = await issueRepo.nextIssueNumber(t.org.id, project!.id as never);
      await issueRepo.insertIssue(
        issueInput(t.org.id, project!.id as never, { title: "late", dueAt: PAST }),
        owner as never,
        number,
      );
    }

    await runOverdueIssueJob(NOW);
    detach();

    for (const t of tenantsWithIssue) expect(seen.has(t.org.id)).toBe(true);
    expect(seen.size).toBeGreaterThanOrEqual(tenantsWithIssue.length);
  });

  it("overdue scan never announces for a deleted workspace", async () => {
    const gone = await createTenant("scratch-overdue-gone");
    await insertLateIssue(gone);
    await orgRepo.archiveOrg(gone.org.id);

    const seenOrgs: string[] = [];
    const detach = subscribe("issue.overdue", (payload) => {
      seenOrgs.push(payload.orgId);
    });
    await runOverdueIssueJob(NOW);
    detach();

    expect(seenOrgs).not.toContain(gone.org.id);
  });

  it("recount takes at most 25 per run, least recently recounted first, and deltas do not move an org", async () => {
    const live = await allLiveIds();
    const total = live.length;

    const head = await usageRepo.listOrgIdsForRollup(25);
    expect(head.length).toBe(Math.min(25, total));
    expect(new Set(head).size).toBe(head.length);

    const order1 = await usageRepo.listOrgIdsForRollup(total + 10);
    expect(order1.slice(0, head.length)).toEqual(head);
    expect(order1).toHaveLength(total);

    const result = await runUsageRollupJob(NOW);
    expect(result.processed).toBe(head.length);
    expect(result.failed).toBe(0);

    const order2 = await usageRepo.listOrgIdsForRollup(total + 10);
    expect(order2).toHaveLength(total);
    expect(new Set(order2.slice(0, total - head.length))).toEqual(
      new Set(order1.slice(head.length)),
    );
    expect(new Set(order2.slice(total - head.length))).toEqual(new Set(head));

    // A delta is not a recount: the front of the queue keeps its place.
    const front = order2[0]!;
    const back = order2[order2.length - 1]!;
    await usageRepo.incrementUsage(front, { issuesUsed: 3 });
    await usageRepo.incrementUsage(back, { seatsUsed: 1 });
    const order3 = await usageRepo.listOrgIdsForRollup(total + 10);
    expect(order3).toEqual(order2);
  });

  it("every live org gets recounted within ceil(total / 25) runs and deleted orgs are never queued", async () => {
    const gone = await createTenant("scratch-recount-gone");
    await orgRepo.archiveOrg(gone.org.id);

    const live = await allLiveIds();
    const runs = Math.ceil(live.length / 25);
    for (let i = 0; i < runs; i += 1) {
      const r = await runUsageRollupJob(NOW);
      expect(r.processed).toBeLessThanOrEqual(25);
    }

    for (const id of live) {
      const usage = await usageRepo.getUsage(id as never);
      expect(usage.measuredAt).not.toBe(NEVER);
    }

    const queued = await usageRepo.listOrgIdsForRollup(10_000);
    expect(queued).not.toContain(gone.org.id);
  });
});

